import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const b=JSON.parse('{"title":"Claude 模型選型官方指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/45-model-selection-guide.md","filePath":"research/best-practices/45-model-selection-guide.md","lastUpdated":1785909234000}'),d={name:"research/best-practices/45-model-selection-guide.md"};function l(s,e,c,i,n,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="claude-模型選型官方指南" tabindex="-1">Claude 模型選型官方指南 <a class="header-anchor" href="#claude-模型選型官方指南" aria-label="Permalink to &quot;Claude 模型選型官方指南&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/claude-models-explained-choosing-the-best-model-for-your-use-case" target="_blank" rel="noreferrer">Claude models explained: choosing the best model for your use case</a>（2026-07-24） 整理日期：2026-08-04</p></blockquote><hr><h2 id="核心主張" tabindex="-1">核心主張 <a class="header-anchor" href="#核心主張" aria-label="Permalink to &quot;核心主張&quot;">​</a></h2><p><strong>從「目前一般可用的最聰明模型」起步，再依延遲、成本、任務難度往下調</strong>——不要從便宜模型往上爬。模型選擇的依據是任務難度、延遲要求、存取限制與單位經濟，<strong>不是產業別</strong>：官方明言每個 Claude 模型都受訓於 coding、agentic 與知識工作，不存在「金融用這個、醫療用那個」的分法。</p><hr><h2 id="四個-class-的定位" tabindex="-1">四個 class 的定位 <a class="header-anchor" href="#四個-class-的定位" aria-label="Permalink to &quot;四個 class 的定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>定位</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>Mythos / Fable</strong></td><td>前沿能力層（Mythos 受限存取、Fable 為含安全機制的公開版）</td><td>最難的長跑任務、需最強判斷</td></tr><tr><td><strong>Opus</strong></td><td>推理密集</td><td>架構決策、深度分析、agentic 主控</td></tr><tr><td><strong>Sonnet</strong></td><td>日常工作與高量 sub-agent</td><td>實作、批次、workers</td></tr><tr><td><strong>Haiku</strong></td><td>成本敏感、高頻</td><td>分類、路由、簡單提取</td></tr></tbody></table><hr><h2 id="effort-等級改變了成本計算" tabindex="-1">Effort 等級改變了成本計算 <a class="header-anchor" href="#effort-等級改變了成本計算" aria-label="Permalink to &quot;Effort 等級改變了成本計算&quot;">​</a></h2><ul><li>Effort 產生「品質 × 速度 × 成本」的連續取捨面，不再是離散的模型選擇。</li><li><strong>高 class 模型跑低 effort，有時 per-task 經濟性優於低 class 模型</strong>——即使 per-token 價格較高。因為完成同一任務所需 token 更少、重試更少。</li><li>因此「每百萬 token 多少錢」不等於「每個任務多少錢」，選型應以後者為準。</li></ul><hr><h2 id="advisor-策略-實測數據" tabindex="-1">Advisor 策略（實測數據） <a class="header-anchor" href="#advisor-策略-實測數據" aria-label="Permalink to &quot;Advisor 策略（實測數據）&quot;">​</a></h2><p>以較快的 worker 模型搭配較聰明的 advisor 模型做驗證，可取得大部分能力而不付全額成本：</p><blockquote><p><strong>Sonnet + Fable 監督 = Fable-only 效能的 90%，成本為 63%。</strong></p></blockquote><p>用法細節見 <code>07-advisor-tool-best-practices.md</code>。</p><hr><h2 id="評估紀律" tabindex="-1">評估紀律 <a class="header-anchor" href="#評估紀律" aria-label="Permalink to &quot;評估紀律&quot;">​</a></h2><ul><li>對強模型而言，<strong>自建 eval 比公開 benchmark 更有意義</strong>：benchmark 已趨飽和，區辨力不足。</li><li>建議建立「策展問題集 + 團隊自訂成功標準」，跑在真實生產工作負載上。</li><li>目的之一是分辨「模型能力不足」與「整合／context 沒接好」——後者遠比前者常見。</li></ul><hr><h2 id="對本-workspace-的映射" tabindex="-1">對本 workspace 的映射 <a class="header-anchor" href="#對本-workspace-的映射" aria-label="Permalink to &quot;對本 workspace 的映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>官方概念</th><th>本 workspace 對應</th></tr></thead><tbody><tr><td>class × effort 選擇</td><td><code>.claude/refs/model-profiles.md</code>（四檔位 cost/quality/ceiling/frontier）</td></tr><tr><td>從最強模型起步再往下調</td><td><code>pilot</code> SKILL 的檔位升級鏈</td></tr><tr><td>Advisor 監督</td><td><code>reviewer</code> / <code>security-reviewer</code> agent 與 <code>multi-mode-agent</code> 異 instance verifier</td></tr><tr><td>自建 eval &gt; benchmark</td><td><code>research/evals/</code> + <code>the-loop-harness-v5</code> fixtures</td></tr></tbody></table><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>44-claude-opus-5.md</code> · <code>41-claude-sonnet-5.md</code> · <code>36-claude-fable-5.md</code> — 各模型規格</li><li><code>07-advisor-tool-best-practices.md</code> — Advisor 架構完整指南</li><li><code>46-context-engineering-claude5.md</code> — Claude 5 世代的 context 撰寫規則</li></ul>',25)])])}const p=t(d,[["render",l]]);export{b as __pageData,p as default};
